connect.lines:
with record: a2a data.connection.url=https://services-internal/facilities/access | authentication.type=bearer authentication.token={{secrets.FACILITIES_BEARER}} | connectorMode.toolOperation.operation=data.flowWorkflowUserOnboardingRequest | connectorMode.toolOperation.params={ offerId: offerId }
with record: email readEmailImap imapMessageIdRead=offerId | authentication.simpleAuthenticationUsername={{secrets.EMAIL_USERNAME}} | authentication.simpleAuthenticationPassword={{secrets.EMAIL_PASSWORD}} | imapHost=imaps://imap.company.com | resultVariable=offerEmail
with record: email deleteEmailImap imapMessageIdDelete=offerId | authentication.simpleAuthenticationPassword={{secrets.EMAIL_PASSWORD}} | data.imapHost=imaps://imap.company.com | authentication.simpleAuthenticationUsername={{secrets.EMAIL_USERNAME}} | resultVariable=offerEmailRead
