with facilities: a2a data.connection.url=https://facilities.app/api/slots | connectorMode.toolOperation.operation=bookSlot | connectorMode.toolOperation.params={ userId: userId, date: today() } | authentication.type=bearer authentication.token={{secrets.FACILITIES_BEARER}}
with slack: slack chat.postMessage data.text== "Welcome " + fullName + "! Your onboarding is underway." | data.channel=#hr | token={{secrets.SLACK_TOKEN}}
with slack: api slack GET /users.lookupByEmail query=email==emailAssignedValue | auth=bearer secret=SLACK_TOKEN
with update: slack chat.postMessage data.text== "Updated org chart for " + emailAssignedValue | data.channel=#management | token={{secrets.SLACK_TOKEN}}

